package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's preferred contact channel: "EMAIL" when an email is present,
 * otherwise "PHONE". A null or blank email counts as no email.
 */
public final class ContactPreference {

    private ContactPreference() {
    }

    /** "EMAIL" when {@code owner} has a non-blank email, otherwise "PHONE". */
    public static String of(Owner owner) {
        String email = owner.getEmail();
        return email != null && !email.isBlank() ? "EMAIL" : "PHONE";
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's numeric membership level (1 to 3) on creation: it starts at
 * 1, gains 1 when an email is present, gains 1 when {@code namesakeCount} is 0,
 * and is capped at 3 (level 4 is reserved for tenure).
 */
public final class MembershipLevel {

    private MembershipLevel() {
    }

    /** Membership level (1 to 3) derived from the owner's email and namesake count. */
    public static int of(Owner owner) {
        int level = 1;
        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
            level += 1;
        }
        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
            level += 1;
        }
        return Math.min(level, 3);
    }
}

